// src/builder/list.ts
var LEADING_UNORDERED = "-";
function list(type, ...nodes) {
  const filteredNodes = nodes.filter((node) => node !== null);
  return {
    toString() {
      let data = "";
      for (const [index, value] of filteredNodes.entries()) {
        const leading = type === "ordered" ? index + 1 : LEADING_UNORDERED;
        data += `${leading} ${value.toString()}
`;
      }
      return data;
    }
  };
}
export {
  list
};
